import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Add your first source","description":"","frontmatter":{"title":"Add your first source"},"headers":[],"relativePath":"docs/getting-started/add-first-source.md","filePath":"docs/getting-started/add-first-source.md","lastUpdated":1790449305000}'),s={name:"docs/getting-started/add-first-source.md"};function n(i,e,c,d,l,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="add-your-first-source" tabindex="-1">Add your first source <a class="header-anchor" href="#add-your-first-source" aria-label="Permalink to &quot;Add your first source&quot;">​</a></h1><p>A <strong>source</strong> is a file (or set of files) that feeds data into a project — a bank statement, a brokerage statement, a CSV export, or a general document. See <a href="/docs/concepts/sources">Sources</a> for how sources relate to the rest of a project; this page covers adding one.</p><h2 id="adding-a-source-to-a-regular-project" tabindex="-1">Adding a source to a regular project <a class="header-anchor" href="#adding-a-source-to-a-regular-project" aria-label="Permalink to &quot;Adding a source to a regular project&quot;">​</a></h2><p>From your project, click <strong>Add Source</strong>. You can:</p><ul><li>Drag and drop files or a whole folder onto the dialog</li><li>Use the file/folder picker</li><li>Paste a URL</li></ul><p>Then choose how OrbySystems should treat what you&#39;re adding:</p><ul><li><strong>Auto Detect</strong> — OrbySystems recognizes bank and brokerage statements automatically, and treats anything else as a general document. This is the right choice most of the time.</li><li><strong>Bank Statement</strong> / <strong>Brokerage</strong> — force detection as one of these if auto-detect guesses wrong.</li><li><strong>General Document</strong> — skip financial parsing entirely.</li></ul><p>As each file is processed you&#39;ll see live progress — files processed, files failed, and how many transactions were found. Once it&#39;s done, the source&#39;s data is queryable in the project.</p><p>Don&#39;t have real statements handy yet, or want to pull them automatically instead of downloading manually? See the <a href="/docs/tools/statement-downloader">Statement downloader</a> tool.</p><h2 id="adding-a-source-to-a-combined-finance-project" tabindex="-1">Adding a source to a Combined Finance project <a class="header-anchor" href="#adding-a-source-to-a-combined-finance-project" aria-label="Permalink to &quot;Adding a source to a Combined Finance project&quot;">​</a></h2><p>A Combined Finance project&#39;s &quot;sources&quot; are other finance projects, not files. Use <strong>Add Source</strong> there to pick which of your existing Income/Spending, Investment, or Fixed Assets projects to combine — OrbySystems keeps them in sync as those source projects change.</p><h2 id="managing-sources" tabindex="-1">Managing sources <a class="header-anchor" href="#managing-sources" aria-label="Permalink to &quot;Managing sources&quot;">​</a></h2><p>The <strong>Sources</strong> view for a project lists everything that&#39;s been added, with per-source actions to remove it, relocate it (if the original file moved), or rescan it (re-run parsing, e.g. after a parser fix).</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>With data in place, browse <a href="/docs/getting-started/browse-recipes">Recipes</a> for instant charts, or jump straight to <a href="/docs/getting-started/ask-questions">asking questions</a>.</p>',15)])])}const p=t(s,[["render",n]]);export{h as __pageData,p as default};
